// Check: validate the request before anything touches the wiki.
const { mode, path, heading, text } = $input.first().json;
const p = String(path || '').trim().replace(/^\/+/, '');
const segments = p.split('/');
if (!p.endsWith('.md') || segments.some((s) => s === '' || s === '..' || s.startsWith('.'))) {
  throw new Error(`Invalid page path "${p}". Use a relative path ending in .md, e.g. Travel/Canada/Quebec/Montreal.md`);
}
// SilverBullet's own library and its sources, mostly Space Lua.
if (/^(library|repositories)$/i.test(segments[0])) {
  throw new Error(`Refused: ${segments[0]}/ holds SilverBullet's own files. Write household pages elsewhere.`);
}
const body = String(text || '').trimEnd();
if (!body.trim()) throw new Error('Nothing to write: text is empty.');
// SilverBullet runs these as code in the browser of everyone who opens the page.
for (const bad of ['space-lua', 'space-style', 'space-script', '${', '<!--#', '<script', '<iframe']) {
  if (body.toLowerCase().includes(bad)) {
    throw new Error(`Refused: the text contains "${bad}", which SilverBullet runs as code. Rewrite it as plain markdown.`);
  }
}
const section = String(heading || '').trim().replace(/^#+\s*/, '');
if (mode === 'append' && !section) throw new Error('append_to_page needs a heading, e.g. Recommendations.');
return [{ json: { mode, path: p, urlPath: segments.map(encodeURIComponent).join('/'), heading: section, text: body } }];

// Edit: build the new page from what is there now, guarded by its ETag.
const req = $('Check').first().json;
const res = $input.first().json;
if (res.statusCode !== 200 && res.statusCode !== 404) throw new Error(`Reading ${req.path} failed: HTTP ${res.statusCode}`);
const exists = res.statusCode === 200;
const title = req.path.replace(/\.md$/, '').split('/').pop();
let content;
if (req.mode === 'create') {
  if (exists) throw new Error(`${req.path} already exists. Read it, then use append_to_page.`);
  content = req.text + '\n';
} else if (!exists) {
  content = `# ${title}\n\n## ${req.heading}\n\n${req.text}\n`;
} else {
  const lines = String(res.body ?? '').replace(/\s+$/, '').split('\n');
  const want = `## ${req.heading}`.toLowerCase();
  const start = lines.findIndex((l) => l.trim().toLowerCase() === want);
  if (start === -1) {
    lines.push('', `## ${req.heading}`, '', req.text);
  } else {
    // The section runs to the next heading of level 1 or 2.
    let end = lines.findIndex((l, i) => i > start && /^#{1,2}\s/.test(l));
    if (end === -1) end = lines.length;
    while (end > start + 1 && lines[end - 1].trim() === '') end--;
    // A list item continues the list above it; anything else is a new paragraph.
    const isItem = (l) => /^\s*([-*+]|\d+\.)\s/.test(l);
    if (isItem(lines[end - 1]) && isItem(req.text)) lines.splice(end, 0, req.text);
    else lines.splice(end, 0, '', req.text);
  }
  content = lines.join('\n') + '\n';
}
return [{
  json: {
    path: req.path,
    urlPath: req.urlPath,
    content,
    added: req.text,
    created: !exists,
    conditionHeader: exists ? 'If-Match' : 'If-None-Match',
    conditionValue: exists ? res.headers.etag : '*',
  },
}];

// Result: what the tool tells the model; a refused write is an error it can act on.
const w = $('Edit').first().json;
const r = $input.first().json;
if (r.statusCode === 412) throw new Error(`${w.path} changed while it was being edited. Read it again and retry.`);
if (r.statusCode >= 300) throw new Error(`Writing ${w.path} failed: HTTP ${r.statusCode}`);
return [{ json: { result: `${w.created ? 'Created' : 'Updated'} ${w.path}`, added: w.added } }];
